import json
import logging
import os
from email.utils import parseaddr


logger = logging.getLogger()
logger.setLevel(logging.INFO)

ALLOWED_RECIPIENT = os.environ.get(
    "ALLOWED_RECIPIENT",
    "",
).strip().lower()

ALLOWED_DOMAINS = {
    value.strip().lower()
    for value in os.environ.get(
        "ALLOWED_SENDER_DOMAINS",
        "",
    ).split(",")
    if value.strip()
}

PASS_STATUSES = {"PASS"}
NON_FAIL_STATUSES = {"PASS", "GRAY", "PROCESSING_FAILED", "NONE", "PENDING"}


def response(disposition: str, reason: str) -> dict:
    logger.info(json.dumps({"disposition": disposition, "reason": reason}))
    return {"disposition": disposition}


def parse_domain(value: str) -> str:
    address = parseaddr(value or "")[1] or (value or "")
    if "@" not in address:
        return ""
    return address.rsplit("@", 1)[1].strip().lower()


def domain_allowed(domain: str) -> bool:
    return any(domain == allowed or domain.endswith(f".{allowed}") for allowed in ALLOWED_DOMAINS)


def handler(event, context):
    try:
        records = event.get("Records", [])
        if not records:
            return response("STOP_RULE_SET", "Event without SES records")

        for record in records:
            ses = record.get("ses", {})
            mail = ses.get("mail", {})
            receipt = ses.get("receipt", {})

            recipients = [str(x).strip().lower() for x in (receipt.get("recipients") or mail.get("destination") or []) if str(x).strip()]
            if ALLOWED_RECIPIENT not in recipients:
                return response("STOP_RULE_SET", f"Recipient not allowed: {recipients}")

            source = str(mail.get("source", "")).strip()
            common_headers = mail.get("commonHeaders", {})
            from_headers = common_headers.get("from") or []
            candidate_sender = source or (from_headers[0] if from_headers else "")
            sender_domain = parse_domain(candidate_sender)

            if not sender_domain or not domain_allowed(sender_domain):
                return response("STOP_RULE_SET", f"Sender domain not allowed: {sender_domain or 'unknown'}")

            spam_status = str((receipt.get("spamVerdict") or {}).get("status", "")).upper()
            virus_status = str((receipt.get("virusVerdict") or {}).get("status", "")).upper()
            spf_status = str((receipt.get("spfVerdict") or {}).get("status", "")).upper()
            dkim_status = str((receipt.get("dkimVerdict") or {}).get("status", "")).upper()

            if spam_status not in PASS_STATUSES:
                return response("STOP_RULE_SET", f"Spam verdict rejected: {spam_status}")

            if virus_status not in PASS_STATUSES:
                return response("STOP_RULE_SET", f"Virus verdict rejected: {virus_status}")

            if spf_status and spf_status not in NON_FAIL_STATUSES:
                return response("STOP_RULE_SET", f"SPF verdict rejected: {spf_status}")

            if dkim_status and dkim_status not in NON_FAIL_STATUSES:
                return response("STOP_RULE_SET", f"DKIM verdict rejected: {dkim_status}")

        return response("CONTINUE", "Message accepted")
    except Exception as exc:
        logger.exception("Unhandled error while validating SES inbound mail")
        return response("STOP_RULE_SET", f"Unhandled exception: {exc}")

import json
import os
import re
import boto3

ses = boto3.client("ses")
s3 = boto3.client("s3")

FROM_ADDRESS = os.environ["SES_FROM_ADDRESS"]
TO_ADDRESSES = [x.strip() for x in os.environ.get("NOTIFICATION_TO", "").split(",") if x.strip()]
CC_ADDRESSES = [x.strip() for x in os.environ.get("NOTIFICATION_CC", "").split(",") if x.strip()]
MUNICIPALITY_NAME = os.environ.get("MUNICIPALITY_NAME", "")
MUNICIPALITY_LOGO_URL = os.environ.get("MUNICIPALITY_LOGO_URL", "")
MUNICIPALITY_URL = os.environ.get("MUNICIPALITY_URL", "")
TEMPLATE_BUCKET = os.environ.get("MAIL_TEMPLATE_BUCKET", "")
TEMPLATE_KEY = os.environ.get("MAIL_TEMPLATE_KEY", "templates/soc_ioc_notification_v1.html")

_template_cache = None

def get_template():
    global _template_cache
    if _template_cache is None and TEMPLATE_BUCKET:
        obj = s3.get_object(Bucket=TEMPLATE_BUCKET, Key=TEMPLATE_KEY)
        _template_cache = obj["Body"].read().decode("utf-8")
    return _template_cache or ""

def render(template, data):
    def replacer(m):
        key = m.group(1).strip()
        parts = key.split("|")
        var = parts[0].strip()
        val = data.get(var, "")
        for filt in parts[1:]:
            filt = filt.strip()
            if filt.startswith("default("):
                if not val:
                    val = filt[8:-1].strip("'\"")
            elif filt.startswith("replace("):
                args = filt[8:-1].split(",")
                if len(args) == 2:
                    val = val.replace(args[0].strip("'\" "), args[1].strip("'\" "))
        return str(val)
    return re.sub(r"\{\{\s*(.*?)\s*\}\}", replacer, template)

def handler(event, context):
    for record in event.get("Records", []):
        body = json.loads(record["body"])
        subject = body.get("subject", "Notificacion SOC")
        text = body.get("text", "")
        to = body.get("to") or TO_ADDRESSES
        cc = body.get("cc") or CC_ADDRESSES
        td = body.get("template_data", {})
        td.setdefault("municipality_name", MUNICIPALITY_NAME)
        td.setdefault("municipality_logo_url", MUNICIPALITY_LOGO_URL)
        td.setdefault("municipality_url", MUNICIPALITY_URL)
        html_template = get_template()
        html_body = render(html_template, td) if html_template else ""
        msg = {
            "Source": FROM_ADDRESS,
            "Destination": {"ToAddresses": to if isinstance(to, list) else [to]},
            "Message": {
                "Subject": {"Data": subject, "Charset": "UTF-8"},
                "Body": {"Text": {"Data": text, "Charset": "UTF-8"}}
            }
        }
        if cc:
            msg["Destination"]["CcAddresses"] = cc if isinstance(cc, list) else [cc]
        if html_body:
            msg["Message"]["Body"]["Html"] = {"Data": html_body, "Charset": "UTF-8"}
        ses.send_email(**msg)
    return {"statusCode": 200}
